#resFormModal" data-item="{{base64_encode(json_encode($d))}}" onclick="openRes(this.dataset.item)" title="Edit">{!!$icon['edit']!!}</button><button class="res-action" data-bs-toggle="modal" data-bs-target="#resStatusModal" data-item="{{base64_encode(json_encode($d))}}" onclick="statusRes(this.dataset.item)" title="Change Status">{!!$icon['status']!!}</button><form method="POST" action="{{route('resignations-destroy',$r)}}" class="res-delete" data-name="{{$r->employee?->name}}">@csrf @method('DELETE')<button class="res-action" title="Delete">{!!$icon['delete']!!}</button></form></div></td></tr>@empty<tr><td colspan="8" class="text-center py-10 text-muted">No resignations found.</td></tr>@endforelse</tbody></table></div><div class="d-flex justify-content-between align-items-center p-5"><span class="text-muted">Showing {{$resignations->firstItem()??0}} to {{$resignations->lastItem()??0}} of {{$resignations->total()}} results</span>{{$resignations->links('pagination::bootstrap-4')}}</div></div></div>
