<script>const rs=@json(route('resignations-store')),ru=@json(route('resignations-update','__ID__')),rt=@json(route('resignations-status','__ID__'));function rd(x){return x?JSON.parse(atob(x)):{} }function openRes(x){let d=rd(x),f=document.getElementById('resForm');f.reset();f.action=rs;resMethod.innerHTML='';resTitle.textContent=d.id?'Edit Resignation':'Add New Resignation';['employee_id','resignation_date','last_working_day','notice_period','reason','description'].forEach(k=>f.elements[k].value=d[k]||'');f.querySelectorAll('.edit-extra').forEach(e=>e.style.display=d.id?'block':'none');if(d.id){f.action=ru.replace('__ID__',d.id);resMethod.innerHTML='<input type="hidden" name="_method" value="PUT">'}}function viewRes(x){let d=rd(x),m=document.getElementById('resViewModal');m.querySelector('[data-rv=avatar]').src=d.avatar;m.querySelector('[data-rv=employee]').textContent=d.employee_name||'—';let b=m.querySelector('[data-rv=status]');b.textContent=d.status;b.className='ms-auto res-badge res-'+d.status.toLowerCase();let v={date:d.resignation_date,last:d.last_working_day,notice:d.notice_period,reason:d.reason,description:d.description};Object.keys(v).forEach(k=>m.querySelector('[data-rv='+k+']').textContent=v[k]||'—');let box=m.querySelector('[data-rv=document]');box.innerHTML=d.document_url?(/\.(png|jpe?g)$/i.test(d.document_path)?'<a target="_blank" href="'+d.document_url+'"><img class="res-preview" src="'+d.document_url+'"></a>':'<a target="_blank" href="'+d.document_url+'">View document</a>'):'—'}function statusRes(x){let d=rd(x),f=document.getElementById('resStatusForm');f.action=rt.replace('__ID__',d.id);f.elements.status.value=d.status;f.querySelector('[type=checkbox]').checked=!!d.exit_interview_conducted;f.elements.exit_interview_date.value=d.exit_interview_date||'';f.elements.exit_feedback.value=d.exit_feedback||''}document.addEventListener('DOMContentLoaded',()=>{let f=document.getElementById('resForm');f.onsubmit=e=>{f.querySelectorAll('.res-error').forEach(x=>x.remove());let first;Object.entries({employee_id:'Employee',resignation_date:'Resignation Date',reason:'Reason'}).forEach(([k,n])=>{let a=f.elements[k];if(!a.value){a.insertAdjacentHTML('afterend','<div class="res-error">'+n+' is required</div>');first=first||a}});if(first){e.preventDefault();first.focus()}};document.querySelectorAll('.res-delete').forEach(f=>f.onsubmit=e=>{if(f.dataset.ok)return;e.preventDefault();Swal.fire({title:'Delete resignation',text:'Are you sure you want to delete '+f.dataset.name+'? This action cannot be undone.',showCancelButton:true,confirmButtonText:'Delete',confirmButtonColor:'#f1416c'}).then(r=>{if(r.isConfirmed){f.dataset.ok=1;f.submit()}})})});</script>
